            result.append(str(i))
    return result

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result += f'{current_char}{count}'
            current_char = char
            count = 1
    result += f'{current_char}{count}'
    return result

